export class HeroCard {
  public readonly hero = input.required<Hero>();

  protected readonly statusVariant = computed(() => STATUS_VARIANT[this.hero().status]);

  /** Up to two initials: the first letters of the first two words, or the first two letters. */
  protected readonly initials = computed(() => {
    const words = this.hero().name.replace(/[^\p{L}\s]/gu, '').trim().split(/\s+/);
